    "scope.page.title": "⟦Thee paagee⟧",
    "scope.page.body": "⟦Theesee coontrools aaree thee oonees iin thee heeaadeer. Theey theemee thee doocuumeent, aand eeveerythiing oon iit thaat haas noot beeeen giiveen aa theemee oof iits oown.⟧",
    "scope.component.title": "⟦Thiis coompooneent⟧",
