export const localeMeta = {
  "en": { name: "English", bcp47: "en", dir: "ltr" },
  "pt-BR": { name: "Português", bcp47: "pt-BR", dir: "ltr" },
  "qps": { name: "Pseudo", bcp47: "qps", dir: "ltr" },
};

export const defaultLocale = "en";
/** Offered to readers. The pseudo-locale is for review, not for reading. */
export const offeredLocales = ["en", "pt-BR"];

/**
 * One message, in one locale.
 *
 * Throws on an unknown key rather than returning it. A key rendered as
 * its own name puts `nav.open` on a button and reports nothing.
 */
export function t(locale, key) {
  const table = messages[locale] ?? messages[defaultLocale];
  const message = table[key];
  if (message === undefined) throw new Error(`no message for ${key}`);
  return message;
}

/**
 * Substitutes `{name}` placeholders.
 *
 * The only sanctioned way to build a message: never concatenate two
 * lookups. Word order, gender and agreement differ between languages, so
 * a whole sentence with a hole in it survives translation and two halves
 * do not.
 */
export function fill(template, args) {
  return template.replace(/\{(\w+)\}/g, (whole, name) =>
    Object.hasOwn(args, name) ? args[name] : whole,
  );
}
